#include <gtest/gtest.h>

#include "DisappearingPairs.hpp"

class DisappearingPairsTest : public testing::Test {};

TEST_F(DisappearingPairsTest, ResolveSimpleExampleString) {
  DisappearingPairs disappearing_pairs;
  std::string test_string("ACCAABBC");
  EXPECT_EQ("AC", disappearing_pairs.Solution(test_string));
}

TEST_F(DisappearingPairsTest, SolutionStringEmpty) {
  DisappearingPairs disappearing_pairs;
  std::string test_string("ABCBBCBA");
  EXPECT_EQ("", disappearing_pairs.Solution(test_string));
}

TEST_F(DisappearingPairsTest, StringNotChangedIfNoRuleApplies) {
  DisappearingPairs disappearing_pairs;
  std::string test_string("BABABA");
  EXPECT_EQ("BABABA", disappearing_pairs.Solution(test_string));
}

TEST_F(DisappearingPairsTest, LongString) {
  DisappearingPairs disappearing_pairs;
  std::string test_string("");
  EXPECT_EQ("", disappearing_pairs.Solution(test_string));
}

TEST_F(DisappearingPairsTest, EmptyString) {
  DisappearingPairs disappearing_pairs;
  std::string empty;
  EXPECT_EQ("", disappearing_pairs.Solution(empty));
}

TEST_F(DisappearingPairsTest, EvenPolindrome) {
  DisappearingPairs disappearing_pairs;
  std::string even_polindrome("ABCAACBA");
  EXPECT_EQ("", disappearing_pairs.Solution(even_polindrome));
}

